#!/usr/bin/env bash
# Unit tests for the short command (veiltrium), --help and --qr. No network, no root.
set -u
cd "$(dirname "$0")/.." || exit 1
# shellcheck source=../veiltrium.sh
source ./veiltrium.sh
set +eE
trap - ERR

FAIL=0
check() {   # got, want, name
    if [[ "$1" == "$2" ]]; then echo "ok   $3"; else echo "FAIL $3: got '$1', want '$2'"; FAIL=1; fi
}
TMPD="$(mktemp -d)"
trap 'rm -rf "${TMPD}"' EXIT

# ---- the wrapper: generated by the installer's function, run with a stub installer
cat > "${TMPD}/stub.sh" <<'EOF'
#!/bin/bash
echo "ARGS:$*"
EOF
cli_wrapper_text "${TMPD}/stub.sh" > "${TMPD}/veiltrium"
chmod 755 "${TMPD}/veiltrium"
bash -n "${TMPD}/veiltrium"; check $? 0 "wrapper: bash -n"
W() { bash "${TMPD}/veiltrium" "$@" 2>&1; }

check "$(W status)" "ARGS:--status" "wrapper: status"
check "$(W clients)" "ARGS:--list-clients" "wrapper: clients"
check "$(W add anna)" "ARGS:--add-client anna" "wrapper: add NAME"
check "$(W remove anna)" "ARGS:--remove-client anna" "wrapper: remove NAME"
check "$(W show anna)" "ARGS:--show-client anna" "wrapper: show NAME"
check "$(W qr main)" "ARGS:--qr main" "wrapper: qr NAME"
check "$(W export /root/x.vt)" "ARGS:--export /root/x.vt" "wrapper: export FILE"
check "$(W russia)" "ARGS:--check-russia" "wrapper: russia"
check "$(W diagnose)" "ARGS:--diagnose" "wrapper: diagnose"
check "$(W panel-password)" "ARGS:--panel-password" "wrapper: panel-password"
check "$(W help)" "ARGS:--help" "wrapper: help"
check "$(W)" "ARGS:--help" "wrapper: no arguments"
check "$(W install)" "ARGS:" "wrapper: install"
check "$(W --dry-run)" "ARGS:--dry-run" "wrapper: an option is passed through"
check "$(W --status --json -)" "ARGS:--status --json -" "wrapper: options with arguments"
check "$(W status --json -)" "ARGS:--status --json -" "wrapper: extra arguments follow the mode"
out="$(W frobnicate)"; rc=$?
check "${rc}" 2 "wrapper: unknown word exits 2"
[[ "${out}" == *"unknown command: frobnicate"* && "${out}" == *"Usage: veiltrium"* ]]; check $? 0 "wrapper: unknown word prints usage"
rm -f "${TMPD}/stub.sh"
out="$(W status)"; rc=$?
check "${rc}" 1 "wrapper: missing installer exits 1"
[[ "${out}" == *"run the installer once"* ]]; check $? 0 "wrapper: missing installer says what to do"

# write_cli_wrapper: written once, same file on a re-run
PANEL_LIB="${TMPD}/lib"
write_cli_wrapper "${TMPD}/cli"
[[ -x "${TMPD}/cli" ]]; check $? 0 "write_cli_wrapper: executable"
before="$(stat -c '%i' "${TMPD}/cli")"
write_cli_wrapper "${TMPD}/cli"
check "$(stat -c '%i' "${TMPD}/cli")" "${before}" "write_cli_wrapper: unchanged text is not rewritten"
[[ ! -e "${TMPD}/cli.new" ]]; check $? 0 "write_cli_wrapper: no leftover file"
grep -q "VT_SCRIPT=${TMPD}/lib/veiltrium.sh" "${TMPD}/cli"; check $? 0 "write_cli_wrapper: runs the installed copy"

# ---- --help: every documented variable is read by the script
help_text="$(usage 2>&1)"
vars="HY2_PORT REALITY_PORT TT_PORT REALITY_ENABLE TT_ENABLE REALITY_FP REALITY_RESELECT PUBLIC_IP SCANNER_BLOCK RU_BLOCKLISTS MTS_MAX_AGE_DAYS VT_AUTO_REBOOT AUTO_REBOOT_TIME VT_RECONFIGURE TRIAL_MINUTES REALITY_CANDIDATES REALITY_SNI HY2_SNI HY2_MASQUERADE_URL TT_SNI PANEL_ENABLE PANEL_PORT GLOBALPING STANDBY_HOSTS NODE_NAME VT_EXPORT_PASSPHRASE VT_IMPORT_PASSPHRASE"
for v in ${vars}; do
    [[ "${help_text}" == *"${v}"* ]]; check $? 0 "help mentions ${v}"
    grep -qE "\\\$\{${v}[:}]|[\"'(\` ]${v}=|read_passphrase ${v}" veiltrium.sh; check $? 0 "script reads ${v}"
done
# every NAME= in the settings part of --help is in the list above
for v in $(printf '%s\n' "${help_text}" | sed -n 's/^  \([A-Z][A-Z0-9_]*\)[= ].*/\1/p'); do
    [[ " ${vars} " == *" ${v} "* ]]; check $? 0 "documented ${v} is in the checked list"
done
[[ "${help_text}" != *"is in README.md"* ]]; check $? 0 "help no longer sends to README for the list"
grep -q '^#    bash veiltrium.sh --qr NAME' veiltrium.sh; check $? 0 "modes header (printed by --help) lists --qr"

# ---- --qr: the links of main and of an added client (stub qrencode)
mkdir -p "${TMPD}/bin"
cat > "${TMPD}/bin/qrencode" <<'EOF'
#!/bin/bash
echo "QR<$(cat)>"
EOF
chmod 755 "${TMPD}/bin/qrencode"
export PATH="${TMPD}/bin:${PATH}"
cat > "${TMPD}/main.txt" <<'EOF'
1) Hysteria 2 link:
hysteria2://main:pw@192.0.2.1:443/?sni=a.com&insecure=1#Veiltrium-PL

   Standby servers (same ports and secrets):
hysteria2://main:pw@192.0.2.9:443/?sni=a.com&insecure=1#Veiltrium-PL-standby1
2) sing-box: "server": "192.0.2.1", see hysteria2://not-a-link-line in text
vless://uuid@192.0.2.1:443?security=reality#Veiltrium-PL
vless://uuid@192.0.2.9:443?security=reality#Veiltrium-PL-standby1
tt://AAAA
tt://BBBB
EOF
cat > "${TMPD}/anna.txt" <<'EOF'
hysteria2://anna:pw2@192.0.2.1:443/?sni=a.com#Veiltrium-PL
vless://uuid2@192.0.2.1:443?security=reality#Veiltrium-PL
tt://CCCC
EOF
check "$(qr_links "${TMPD}/main.txt" | wc -l | tr -d ' ')" 6 "qr: main has 6 link lines (prose is ignored)"
check "$(qr_links "${TMPD}/anna.txt" | sed 's/:.*//' | paste -sd,)" "hysteria2,vless,tt" "qr: an added client has 3 links in order"
out="$(qr_show "${TMPD}/main.txt")"
[[ "${out}" == *"Hysteria 2 (Veiltrium-PL)"* && "${out}" == *"Hysteria 2 (Veiltrium-PL-standby1)"* \
   && "${out}" == *"VLESS Reality (Veiltrium-PL-standby1)"* && "${out}" == *"TrustTunnel"* ]]; check $? 0 "qr: captions, standby included"
[[ "${out}" == *"QR<hysteria2://main:pw@192.0.2.9:443/?sni=a.com&insecure=1#Veiltrium-PL-standby1>"* ]]; check $? 0 "qr: the link is the QR payload"
check "$(printf '%s\n' "${out}" | grep -c '^QR<')" 6 "qr: one code per link"
out="$(qr_show "${TMPD}/anna.txt")"
[[ "${out}" == *"QR<hysteria2://anna:pw2@"* && "${out}" == *"QR<vless://uuid2@"* && "${out}" == *"QR<tt://CCCC>"* \
   && "${out}" != *"main:pw"* ]]; check $? 0 "qr: an added client gets only its own links"
: > "${TMPD}/empty.txt"
( qr_show "${TMPD}/empty.txt" ) >/dev/null 2>&1; check $? 1 "qr: a file without links fails"

if (( FAIL )); then echo "FAILED"; exit 1; fi
echo "all unit-cli tests passed"
